import{_ as o,o as l,c as a,ae as i}from"./chunks/framework.B3uLoxsb.js";const p=JSON.parse('{"title":"Source: docs/RULES.md","description":"","frontmatter":{},"headers":[],"relativePath":"reference/source/rules.md","filePath":"reference/source/rules.md","lastUpdated":1771052491000}'),r={name:"reference/source/rules.md"};function t(d,e,s,c,n,u){return l(),a("div",null,[...e[0]||(e[0]=[i('<h1 id="source-docs-rules-md" tabindex="-1">Source: docs/RULES.md <a class="header-anchor" href="#source-docs-rules-md" aria-label="Permalink to &quot;Source: docs/RULES.md&quot;">​</a></h1><h1 id="rules-model" tabindex="-1">Rules Model <a class="header-anchor" href="#rules-model" aria-label="Permalink to &quot;Rules Model&quot;">​</a></h1><p>This repository uses a layered rules model for the <code>codex-native</code> profile.</p><p>Rules are designed to make execution more deterministic and auditable while keeping domain flexibility.</p><h2 id="scope" tabindex="-1">Scope <a class="header-anchor" href="#scope" aria-label="Permalink to &quot;Scope&quot;">​</a></h2><p>Rules live at:</p><ul><li><code>skills/codex-workflows/templates/codex-native/.agent/rules/</code></li></ul><p>The model has three layers:</p><ol><li>Global rules</li></ol><ul><li>directory: <code>rules/global/</code></li><li>applies to every workflow and domain</li></ul><ol start="2"><li>Domain rules</li></ol><ul><li>directory: <code>rules/domains/</code></li><li>activated when relevant domains are in scope (for example backend, security, QA, game development)</li></ul><ol start="3"><li>Workflow rules</li></ol><ul><li>directory: <code>rules/workflows/</code></li><li>one rule file per workflow contract in <code>workflows/*.md</code></li></ul><h2 id="rule-resolution" tabindex="-1">Rule Resolution <a class="header-anchor" href="#rule-resolution" aria-label="Permalink to &quot;Rule Resolution&quot;">​</a></h2><p>Resolution order is cumulative:</p><ol><li>Load <code>rules/CODEX.md</code></li><li>Merge <code>rules/global/*.md</code></li><li>Merge matching <code>rules/domains/*.md</code></li><li>Enforce selected <code>rules/workflows/&lt;workflow&gt;.md</code></li></ol><p>Workflow rules are final execution gates for phase behavior.</p><h2 id="validation" tabindex="-1">Validation <a class="header-anchor" href="#validation" aria-label="Permalink to &quot;Validation&quot;">​</a></h2><p>The layered model is enforced by:</p><ul><li><code>python skills/codex-workflows/scripts/check_codex_native_rules.py --native-root skills/codex-workflows/templates/codex-native/.agent</code></li></ul><p>Checks include:</p><ul><li>entry rule presence (<code>rules/CODEX.md</code>)</li><li>minimum global and domain rule counts</li><li>minimum content size to avoid placeholder stubs</li><li>one-to-one workflow rule coverage for <code>workflows/*.md</code></li></ul><p>CI also runs this gate in <code>.github/workflows/ci.yml</code>.</p><h2 id="maintenance" tabindex="-1">Maintenance <a class="header-anchor" href="#maintenance" aria-label="Permalink to &quot;Maintenance&quot;">​</a></h2><p>When adding or renaming workflows:</p><ol><li>update <code>templates/codex-native/.agent/workflows/*.md</code></li><li>add or rename matching file in <code>templates/codex-native/.agent/rules/workflows/*.md</code></li><li>run: <code>python skills/codex-workflows/scripts/check_codex_native_rules.py --native-root skills/codex-workflows/templates/codex-native/.agent</code></li></ol>',27)])])}const h=o(r,[["render",t]]);export{p as __pageData,h as default};
